<script>
  Proto.initTopbar('dev');
  document.getElementById('backConfig').href = Proto.href('05-agent-detail.html');

  var currentId = 'sk_report';
  var editingId = null;
  var search = document.getElementById('skillManageSearch');
  var category = document.getElementById('skillManageCategory');
  var statusSel = document.getElementById('skillManageStatus');
  var listBox = document.getElementById('skillManageList');
  var createModal = document.getElementById('skillCreateModal');
  var detailModal = document.getElementById('skillDetailModal');

  function catalog() {
    return Proto.getSkillCatalog ? Proto.getSkillCatalog() : Proto.skillCatalog;
  }

  function statusTag(status) {
    var st = Proto.skillStatusLabel(status);
    return '<span class="tag ' + st[1] + '">' + st[0] + '</span>';
  }

  function renderList() {
    var q = (search.value || '').trim();
    var c = category.value;
    var st = statusSel.value;
    var rows = catalog().filter(function (s) {
      var hit = !q || (s.name + s.prompt + s.category + s.scenario).indexOf(q) >= 0;
      return hit && (!c || s.category === c) && (!st || s.status === st);
    });
    if (!rows.length) {
      listBox.innerHTML = '<tr><td colspan="7"><div class="empty-state" style="padding:32px;">鏆傛棤鍖归厤 Skill</div></td></tr>';
      return;
    }
    listBox.innerHTML = rows.map(function (s) {
      var updated = s.updatedAt || '2026-05-28';
      return '<tr>' +
        '<td><strong>' + s.name + '</strong><div class="skill-table-version">' + s.version + '</div></td>' +
        '<td><div class="desc-cell">' + s.prompt + '</div></td>' +
        '<td>' + s.category + '</td>' +
        '<td>' + statusTag(s.status) + '</td>' +
        '<td>' + s.scope + '</td>' +
        '<td>' + updated + '</td>' +
        '<td class="skill-table-actions">' +
          '<button class="btn btn-sm" data-view-skill="' + s.id + '">璇︽儏</button>' +
          '<button class="btn btn-sm" data-edit-skill="' + s.id + '">缂栬緫</button>' +
          (s.status === 'draft' ? '<button class="btn btn-sm btn-primary" data-enable-skill="' + s.id + '">鍚敤</button>' : '') +
        '</td>' +
      '</tr>';
    }).join('');
    listBox.querySelectorAll('[data-view-skill]').forEach(function (btn) {
      btn.onclick = function () { openDetail(btn.getAttribute('data-view-skill'), false); };
    });
    listBox.querySelectorAll('[data-edit-skill]').forEach(function (btn) {
      btn.onclick = function () { openCreate(btn.getAttribute('data-edit-skill')); };
    });
    listBox.querySelectorAll('[data-enable-skill]').forEach(function (btn) {
      btn.onclick = function () { enableSkill(btn.getAttribute('data-enable-skill')); };
    });
  }

  function openCreate(id) {
    var s = id ? Proto.skillById(id) : null;
    editingId = id || null;
    document.getElementById('skillFormTitle').textContent = id ? '缁х画缂栬緫 Skill' : '鏂板缓 Skill';
    document.getElementById('skillFormName').value = s ? s.name : '';
    document.getElementById('skillFormCategory').value = s ? s.category : '杈撳嚭瑙勮寖';
    document.getElementById('skillFormDesc').value = s ? s.prompt : '';
    document.getElementById('skillFormScenario').value = s ? s.scenario : '';
    document.getElementById('skillFormScope').value = s ? s.scope : '鍏ㄥ叕鍙?;
    document.getElementById('skillFormContent').value = s ? s.prompt : '';
    document.getElementById('skillFormOutput').value = s ? s.output : '';
    createModal.classList.add('active');
  }

  function closeCreate() { createModal.classList.remove('active'); }

  function readForm() {
    return {
      id: editingId,
      name: document.getElementById('skillFormName').value.trim() || '鏈懡鍚?Skill',
      category: document.getElementById('skillFormCategory').value,
      prompt: document.getElementById('skillFormDesc').value.trim() || document.getElementById('skillFormContent').value.trim(),
      scenario: document.getElementById('skillFormScenario').value.trim() || '鏈缃?,
      scope: document.getElementById('skillFormScope').value,
      output: document.getElementById('skillFormOutput').value.trim() || '鎸夋妧鑳藉唴瀹硅緭鍑?
    };
  }

  function openDetail(id, fromDraft) {
    var s = Proto.skillById(id);
    if (!s) return;
    currentId = id;
    var st = Proto.skillStatusLabel(s.status);
    document.getElementById('skillDetailTitle').textContent = s.name;
    document.getElementById('skillDetailSub').textContent = fromDraft ? '鑽夌宸蹭繚瀛橈紝鍙户缁紪杈戙€佸惎鐢ㄦ垨杩斿洖鍒楄〃銆? : '鏌ョ湅璧勬簮閰嶇疆涓庡紩鐢ㄦ儏鍐点€?;
    document.getElementById('skillDetailBody').innerHTML =
      '<div class="skill-detail-meta"><span>' + st[0] + '</span><span>' + s.category + '</span><span>' + s.version + '</span><span>' + s.scope + '</span></div>' +
      '<div class="ops-kv"><span class="k">鎻忚堪</span><span>' + s.prompt + '</span></div>' +
      '<div class="ops-kv"><span class="k">閫傜敤鍦烘櫙</span><span>' + s.scenario + '</span></div>' +
      '<div class="ops-kv"><span class="k">鎶€鑳藉唴瀹?/span><span>' + s.prompt + '</span></div>' +
      '<div class="ops-kv"><span class="k">杈撳嚭瑕佹眰</span><span>' + s.output + '</span></div>' +
      '<div class="ops-kv"><span class="k">寮曠敤 / 浼氳瘽</span><span>' + (s.status === 'enabled' ? '12 / 86' : '0 / 0') + '</span></div>';
    document.getElementById('skillDetailFoot').innerHTML =
      '<button class="btn" id="detailBackList">杩斿洖鍒楄〃</button>' +
      '<button class="btn" id="detailEdit">缁х画缂栬緫</button>' +
      (s.status === 'draft' ? '<button class="btn btn-primary" id="detailEnable">鍚敤</button>' : '');
    document.getElementById('detailBackList').onclick = function () { detailModal.classList.remove('active'); };
    document.getElementById('detailEdit').onclick = function () { detailModal.classList.remove('active'); openCreate(id); };
    var enable = document.getElementById('detailEnable');
    if (enable) enable.onclick = function () { enableSkill(id); detailModal.classList.remove('active'); };
    detailModal.classList.add('active');
  }

  function enableSkill(id) {
    Proto.updateSkillStatus(id, 'enabled');
    renderList();
    Proto.toast('Skill 宸插惎鐢紝鍙湪閰嶇疆椤靛拰瀵硅瘽椤甸€夋嫨');
  }

  [search, category, statusSel].forEach(function (el) {
    el.oninput = renderList;
    el.onchange = renderList;
  });
  document.getElementById('btnRefreshSkill').onclick = function () {
    Proto.toast('宸插埛鏂?Skills 鍒楄〃');
    renderList();
  };
  document.getElementById('btnCreateSkill').onclick = function () { openCreate(); };
  document.getElementById('skillCreateClose').onclick = closeCreate;
  document.getElementById('skillCreateCancel').onclick = closeCreate;
  document.getElementById('skillCreateSave').onclick = function () {
    var draft = Proto.saveSkillDraft(readForm());
    closeCreate();
    renderList();
    openDetail(draft.id, true);
    Proto.toast('宸蹭繚瀛?Skill 鑽夌');
  };
  document.getElementById('skillDetailClose').onclick = function () { detailModal.classList.remove('active'); };

  renderList();
</script>
