  font-size: 14px; border: 1px solid var(--border);
  background: var(--bg-white); color: var(--text);
  transition: all 0.15s;
}
.btn:hover { border-color: var(--primary); color: var(--primary); }
.btn-primary {
  background: var(--primary); border-color: var(--primary); color: #fff;
}
.btn-primary:hover { background: var(--primary-hover); border-color: var(--primary-hover); color: #fff; }
.btn-large { padding: 10px 20px; font-size: 15px; }
.btn-sm { padding: 4px 10px; font-size: 12px; }
.btn-ghost { border-color: transparent; background: transparent; }

/* === 鏍囩 === */
.tag {
  display: inline-block; padding: 2px 10px; border-radius: 4px;
  font-size: 12px; font-weight: 500;
}
.tag-info { background: #d0ebff; color: #1864ab; }
.tag-ok { background: #d3f9d8; color: #2b8a3e; }
.tag-warn { background: #fff4e6; color: #e67700; }
.tag-danger { background: #ffe3e3; color: var(--danger); }
.tag-muted { background: #f1f3f5; color: #495057; }
.tag-dev { background: #E3F2FD; color: #2196F3; }
.tag-review { background: #FFF3E0; color: #F57C00; }
.tag-pending { background: #E0F7FA; color: #00ACC1; }
.tag-published { background: #E8F5E9; color: #388E3C; }
.tag-offline { background: #ECEFF1; color: #607D8B; }
.tag-maintain { background: #FFF8E1; color: #FFA000; }
.tag-archive { background: #ECEFF1; color: #455A64; }

/* === 绛涢€夋潯 === */
.filter-bar {
  display: flex; align-items: center; gap: 16px;
  padding: 16px 20px; background: var(--bg-white);
  border: 1px solid var(--border); border-radius: var(--radius-lg);
  margin-bottom: 16px; flex-wrap: wrap;
}
.filter-group { display: flex; align-items: center; gap: 8px; }
.filter-label { font-size: 13px; color: var(--text-muted); }
.filter-pills {
  display: flex; gap: 4px; background: #f1f3f5; padding: 3px; border-radius: var(--radius-md);
}
.filter-pills button {
  border: none; background: transparent; padding: 4px 12px;
  font-size: 12px; color: var(--text-muted); border-radius: 6px; cursor: pointer;
}
.filter-pills button.active {
  background: #fff; color: var(--primary); font-weight: 500;
  box-shadow: 0 1px 2px rgba(0,0,0,0.06);
}
.filter-search {
  margin-left: auto; width: 200px; padding: 6px 12px;
  border: 1px solid var(--border); border-radius: var(--radius-md); font-size: 13px;
}

/* === Agent 鍗＄墖缃戞牸 === */
.agent-grid {
  display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px;
}
.agent-card {
  background: var(--bg-white); border: 1px solid var(--border);
  border-radius: var(--radius-lg); padding: 16px;
  box-shadow: var(--shadow-sm);
  transition: all 0.15s; cursor: pointer;
  display: block; text-decoration: none; color: inherit;
}
.agent-card:hover {
  border-color: var(--primary); box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}
.agent-card .head { display: flex; gap: 12px; margin-bottom: 12px; }
.agent-card .ic {
  width: 44px; height: 44px; border-radius: 10px;
  display: flex; align-items: center; justify-content: center;
  color: #fff; font-size: 20px; flex-shrink: 0;
}
.ic-blue { background: linear-gradient(135deg, #1677FF, #4096FF); }
.ic-green { background: linear-gradient(135deg, #52C41A, #95DE64); }
.ic-purple { background: linear-gradient(135deg, #722ED1, #B37FEB); }
.ic-orange { background: linear-gradient(135deg, #FA8C16, #FFC069); }
.ic-cyan { background: linear-gradient(135deg, #13C2C2, #5CDBD3); }
.ic-pink { background: linear-gradient(135deg, #EB2F96, #FF85C0); }
.agent-card .name { font-size: 15px; font-weight: 600; margin-bottom: 2px; }
.agent-card .desc {
  font-size: 12px; color: var(--text-muted); line-height: 1.5;
  height: 36px; overflow: hidden;
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical;
}
.agent-card .meta {
  display: flex; align-items: center; justify-content: space-between;
  margin-top: 12px; font-size: 12px; color: var(--text-muted);
}
.agent-card .meta .tags { display: flex; gap: 4px; flex-wrap: wrap; }

/* === 妯℃€佹 === */
.modal-overlay {
  position: fixed; inset: 0; background: rgba(0,0,0,0.45);
  display: flex; align-items: center; justify-content: center; z-index: 100;
}
.modal-box {
  background: var(--bg-white); border-radius: var(--radius-lg);
  width: 680px; max-height: 88vh; display: flex; flex-direction: column;
  box-shadow: var(--shadow-lg); overflow: hidden;
}
.modal-header {
  display: flex; align-items: center; justify-content: space-between;
  padding: 16px 24px; border-bottom: 1px solid var(--border);
}
.modal-header h2 { font-size: 16px; font-weight: 600; }
.modal-header .close {
  width: 32px; height: 32px; border-radius: var(--radius-sm);
  border: none; background: transparent; color: var(--text-muted); font-size: 18px;
}
.modal-header .close:hover { background: var(--bg-hover); color: var(--text); }
.modal-body { padding: 20px 24px; overflow-y: auto; flex: 1; }
.modal-footer {
  display: flex; justify-content: flex-end; gap: 10px;
  padding: 12px 24px; border-top: 1px solid var(--border);
}

/* === 琛ㄥ崟 === */
.form-section {
  border-left: 3px solid var(--primary);
  padding: 4px 0 4px 12px; margin-bottom: 6px; margin-top: 8px;
  font-size: 14px; font-weight: 600; color: var(--text);
}
.form-row { display: flex; align-items: flex-start; gap: 16px; margin-bottom: 16px; }
.form-label {
  width: 96px; flex-shrink: 0; text-align: right;
  padding-top: 8px; font-size: 14px; color: var(--text);
}
.form-label.required::before { content: "*"; color: var(--danger); margin-right: 4px; }
.form-control { flex: 1; min-width: 0; }
.input, .textarea, .select {
  width: 100%; padding: 7px 11px;
  border: 1px solid var(--border); border-radius: var(--radius-md);
  font-size: 14px; font-family: inherit; color: var(--text);
  background: var(--bg-white); transition: border-color 0.15s;
}
.input:focus, .textarea:focus, .select:focus {
  outline: none; border-color: var(--primary);
  box-shadow: 0 0 0 2px rgba(0,61,166,0.12);
}
.textarea { resize: vertical; min-height: 80px; }
.select { appearance: none; background-image: url("data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='10' height='6' viewBox='0 0 10 6'%3E%3Cpath fill='%236B7280' d='M5 6 0 0h10z'/%3E%3C/svg%3E"); background-repeat: no-repeat; background-position: right 12px center; padding-right: 32px; }
.help-text { font-size: 12px; color: var(--text-muted); margin-top: 4px; }

/* 鍥炬爣涓婁紶 */
.icon-uploader {
  width: 56px; height: 56px; border: 1px dashed var(--border);
  border-radius: var(--radius-md);
  display: flex; align-items: center; justify-content: center;
  color: var(--text-muted); font-size: 20px;
  background: var(--bg-page); cursor: pointer;
}
.icon-uploader:hover { border-color: var(--primary); color: var(--primary); background: var(--primary-light); }

/* 绫诲瀷鍗＄墖閫夋嫨 */
.type-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 12px; }
.type-card {
  border: 1.5px solid var(--border); border-radius: var(--radius-md);
  padding: 12px; cursor: pointer; transition: all 0.15s;
  display: flex; gap: 10px; align-items: flex-start;
}
.type-card:hover { border-color: var(--primary); }
.type-card.active { border-color: var(--primary); background: var(--primary-light); }
.type-card .ti {
  width: 32px; height: 32px; border-radius: 6px;
  background: var(--primary-light); display: flex; align-items: center; justify-content: center;
  color: var(--primary); font-size: 16px; flex-shrink: 0;
}
.type-card.active .ti { background: var(--primary); color: #fff; }
.type-card .tn { font-size: 14px; font-weight: 500; margin-bottom: 2px; }
.type-card .td { font-size: 12px; color: var(--text-muted); line-height: 1.4; }

/* === 璇︽儏椤典笁鍒楀竷灞€ === */
.editor-layout {
  display: grid; grid-template-columns: 220px 1fr 380px; gap: 16px;
  height: calc(100vh - var(--topnav-h) - 48px);
}
.editor-nav {
  background: var(--bg-white); border: 1px solid var(--border);
  border-radius: var(--radius-lg); padding: 12px 8px; overflow-y: auto;
}
.editor-nav .item {
  display: flex; align-items: center; gap: 10px;
  padding: 9px 12px; border-radius: var(--radius-md);
  font-size: 13px; color: var(--text-secondary); cursor: pointer; margin-bottom: 2px;
}
.editor-nav .item:hover { background: var(--bg-hover); }
.editor-nav .item.active { background: var(--primary-light); color: var(--primary); font-weight: 500; }
.editor-content {
  background: var(--bg-white); border: 1px solid var(--border);
  border-radius: var(--radius-lg); padding: 24px 28px; overflow-y: auto;
}
.editor-content h2 { font-size: 18px; margin-bottom: 4px; }
.editor-content .h-sub { font-size: 13px; color: var(--text-muted); margin-bottom: 24px; }
.config-panel { display: none; }
.config-panel.active { display: block; }

/* 璋冭瘯闈㈡澘 */
.debug-panel {
  background: var(--bg-white); border: 1px solid var(--border);
  border-radius: var(--radius-lg); display: flex; flex-direction: column;
}
.debug-panel .dh {
  padding: 12px 16px; border-bottom: 1px solid var(--border);
  font-size: 13px; font-weight: 500;
  display: flex; align-items: center; justify-content: space-between;
}
.debug-panel .db { flex: 1; padding: 16px; overflow-y: auto; display: flex; flex-direction: column; gap: 10px; }
.debug-panel .bubble { padding: 10px 12px; border-radius: 10px; font-size: 13px; max-width: 88%; line-height: 1.5; }
.debug-panel .bubble-user { background: var(--primary-light); color: var(--primary); align-self: flex-end; border-bottom-right-radius: 2px; }
.debug-panel .bubble-bot { background: var(--bg-page); color: var(--text); align-self: flex-start; border-bottom-left-radius: 2px; }
.debug-panel .di { padding: 12px; border-top: 1px solid var(--border); display: flex; gap: 8px; }
.debug-panel .di input {
  flex: 1; padding: 7px 11px; border: 1px solid var(--border); border-radius: var(--radius-md); font-size: 13px;
}

/* 鍙屽钩鍙版槧灏勫崱鐗?*/
.mapping-card {
  background: linear-gradient(135deg, #d9e2ff 0%, #e7f5ff 100%);
  border: 1px solid #a5b4e8; border-radius: var(--radius-lg);
  padding: 16px; margin-top: 20px;
  display: flex; align-items: center; gap: 24px;
}
.mapping-card .side { flex: 1; }
.mapping-card .side .lbl {
  font-size: 11px; color: var(--text-muted); letter-spacing: 0.05em;
  text-transform: uppercase; margin-bottom: 4px;
}
.mapping-card .side .val {
  font-family: ui-monospace, "SF Mono", Menlo, monospace;
  font-size: 14px; font-weight: 600; color: var(--text);
}
.mapping-card .arrow { font-size: 22px; color: var(--primary); }
.mapping-card .status { margin-left: auto; }

/* 璧勬簮閫夋嫨鍒楄〃 */
.resource-list { border: 1px solid var(--border); border-radius: var(--radius-md); overflow: hidden; }
.resource-item {
  display: flex; align-items: center; gap: 12px;
  padding: 12px 16px; border-bottom: 1px solid var(--border);
  cursor: pointer; transition: background 0.1s;
}
.resource-item:last-child { border-bottom: none; }
.resource-item:hover { background: var(--bg-hover); }
.resource-item input[type="radio"], .resource-item input[type="checkbox"] { accent-color: var(--primary); }

/* 寮€鍙戝钩鍙拌烦杞摼鎺?*/
.dev-link {
  display: inline-flex; align-items: center; gap: 4px;
  font-size: 13px; color: var(--primary); text-decoration: none; margin-top: 12px;
}
.dev-link:hover { color: var(--primary-hover); }

/* 搴曢儴鍙屽钩鍙扮姸鎬佹爮 */
.dual-status-bar {
  position: fixed; bottom: 0; left: 0; right: 0; height: 36px;
  background: var(--bg-white); border-top: 1px solid var(--border);
  display: flex; align-items: center; padding: 0 24px;
  font-size: 12px; color: var(--text-muted); gap: 16px; z-index: 50;
}
.dual-status-bar .dot { width: 6px; height: 6px; border-radius: 50%; display: inline-block; margin-right: 6px; }
.dual-status-bar .spacer { margin-left: auto; }

/* 绌虹姸鎬?*/
.empty-state {
  padding: 48px 24px; text-align: center;
  border: 1px dashed var(--border); border-radius: var(--radius-md);
  color: var(--text-muted);
}
.empty-state .empty-icon { font-size: 40px; margin-bottom: 12px; }

/* 鍙戝竷璁剧疆鏃堕棿绾?*/
.publish-timeline {
  padding: 12px 0 12px 16px; border-left: 2px solid var(--border);
}
.publish-timeline .tl-item {
  position: relative; padding: 0 0 20px 20px; font-size: 13px;
}
.publish-timeline .tl-item::before {
  content: ""; position: absolute; left: -22px; top: 5px;
  width: 8px; height: 8px; border-radius: 50%; background: var(--border);
}
.publish-timeline .tl-item.done::before { background: var(--success); }
.publish-timeline .tl-item.current::before { background: var(--primary); }
.publish-timeline .tl-item .tl-time { font-size: 11px; color: var(--text-muted); }
.publish-timeline .tl-item .tl-action { font-weight: 500; margin-bottom: 2px; }
.publish-timeline .tl-item .tl-note { font-size: 12px; color: var(--text-muted); }

/* === 鍓嶅線寮€鍙戝钩鍙版寜閽?=== */
.btn-dev-platform {
  display: inline-flex; align-items: center; gap: 4px;
  padding: 6px 16px; border-radius: 20px;
  font-size: 13px; font-weight: 500;
  border: 1.5px solid var(--primary); color: var(--primary);
  background: transparent; white-space: nowrap;
  transition: all 0.15s;
}
.btn-dev-platform:hover { background: var(--primary-light); }

/* === 姝ラ鎸囩ず鍣紙鍒涘缓寮圭獥锛?=== */
.step-indicator {
  display: flex; align-items: center; gap: 8px;
  padding: 6px 24px; background: var(--bg-page);
  border-top: 1px solid var(--border);
  font-size: 12px; color: var(--text-muted);
}
.step-indicator .st {
  width: 20px; height: 20px; border-radius: 50%;
  background: var(--border); color: #fff;
  display: flex; align-items: center; justify-content: center;
  font-size: 11px; font-weight: 600;
}
.step-indicator .st.done { background: var(--success); }
.step-indicator .st.current { background: var(--primary); }
.step-indicator .st-line { flex: 1; height: 2px; background: var(--border); }
.step-indicator .st-line.done { background: var(--success); }

/* === loading === */
@keyframes spin { to { transform: rotate(3…3109 tokens truncated…in-top: 24px; padding: 12px; border-top: 1px solid var(--border);
  font-size: 12px; line-height: 1.6; color: var(--text-muted);
}
.dev-main { flex: 1; padding: 24px; overflow: auto; }
.topbar-modules a.nav-dev.active { color: #087f5b; box-shadow: inset 0 -2px 0 #087f5b; }
.dev-editor-page { height: calc(100vh - var(--topnav-h) - 57px - 44px); }
.dev-editor-page.with-sync { height: calc(100vh - var(--topnav-h) - 57px - 44px - 45px); }

/* === 鏅鸿兘浣撴牳蹇冮厤缃紙瀵归綈寮€鍙戝钩鍙帮級 === */
.dev-col-core { min-width: 0; }
.core-config-scroll { padding: 12px !important; overflow-y: auto; }
.core-config { display: flex; flex-direction: column; gap: 10px; }
.core-section {
  background: var(--bg-white); border: 1px solid var(--border);
  border-radius: var(--radius-md); overflow: hidden;
}
.core-section-head {
  display: flex; align-items: center; gap: 8px;
  padding: 12px 14px; cursor: pointer; user-select: none;
  font-size: 14px; font-weight: 600; color: var(--text);
  background: #fafbfc;
}
.core-section-head:hover { background: var(--bg-hover); }
.core-chevron { font-size: 10px; color: var(--text-muted); transition: transform .2s; }
.core-section.collapsed .core-chevron { transform: rotate(-90deg); }
.core-section.collapsed .core-section-body { display: none; }
.core-section-body { padding: 12px 14px 14px; }
.core-field { margin-bottom: 14px; }
.core-field > label {
  display: block; font-size: 13px; color: var(--text-secondary);
  margin-bottom: 8px;
}
.core-select-wrap {
  display: flex; align-items: center; gap: 8px;
}
.core-select { flex: 1; padding: 8px 10px; font-size: 13px; }
.core-seg { margin-top: 0; }
.core-seg button { font-size: 12px; padding: 6px 8px; }
.core-slider {
  display: grid; grid-template-columns: 100px 1fr 72px;
  align-items: center; gap: 10px;
}
.core-slider > label { margin: 0; }
.core-subhead {
  font-size: 13px; font-weight: 600; color: var(--text);
  margin: 16px 0 10px; padding-top: 12px;
  border-top: 1px dashed var(--border);
}
.core-row-link {
  display: flex; align-items: center; justify-content: space-between;
  padding: 10px 0; font-size: 13px; color: var(--text);
  border-bottom: 1px solid var(--border);
}
.core-row-link:last-child { border-bottom: none; }
.core-row-actions { display: flex; align-items: center; gap: 6px; }
.core-jump {
  display: inline-flex; align-items: center; justify-content: center;
  width: 28px; height: 28px; border-radius: var(--radius-sm);
  color: var(--text-muted); border: 1px solid var(--border);
  background: var(--bg-white); text-decoration: none;
}
.core-jump:hover { color: var(--primary); border-color: var(--primary); background: var(--primary-light); }
.core-icon-btn {
  width: 28px; height: 28px; border-radius: var(--radius-sm);
  border: 1px solid var(--border); background: var(--bg-white);
  color: var(--text-muted); font-size: 16px; line-height: 1; cursor: pointer;
}
.core-icon-btn:hover { color: var(--primary); border-color: var(--primary); }
.core-tags { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 10px; }
.core-tag {
  font-size: 12px; padding: 4px 10px; border-radius: 12px;
  background: var(--bg-page); border: 1px solid var(--border); color: var(--text-secondary);
}
.core-resource-block {
  margin-top: 10px;
  padding: 12px;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: #fcfdff;
}
.core-resource-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 10px;
}
.core-resource-head strong {
  display: block;
  font-size: 13px;
  color: var(--text);
}
.core-resource-head span {
  display: block;
  margin-top: 2px;
  font-size: 12px;
  color: var(--text-muted);
  line-height: 1.4;
}
.switch-sm { transform: scale(0.85); transform-origin: right center; }

/* === 瀹℃牳杩涘害鏉?=== */
.audit-progress-page { max-width: 880px; margin: 0 auto; padding: 24px; }
.audit-stepper {
  display: flex; align-items: flex-start; justify-content: space-between;
  margin: 32px 0 28px; position: relative;
}
.audit-stepper::before {
  content: ""; position: absolute; top: 18px; left: 8%; right: 8%;
  height: 2px; background: var(--border); z-index: 0;
}
.audit-step {
  flex: 1; text-align: center; position: relative; z-index: 1;
  padding: 0 8px;
}
.audit-step .dot {
  width: 36px; height: 36px; border-radius: 50%;
  background: var(--bg-white); border: 2px solid var(--border);
  display: flex; align-items: center; justify-content: center;
  margin: 0 auto 10px; font-size: 14px; color: var(--text-muted);
}
.audit-step.done .dot { background: var(--success); border-color: var(--success); color: #fff; }
.audit-step.current .dot { background: var(--primary); border-color: var(--primary); color: #fff; box-shadow: 0 0 0 4px var(--primary-light); }
.audit-step .label { font-size: 13px; font-weight: 600; color: var(--text); }
.audit-step .sub { font-size: 11px; color: var(--text-muted); margin-top: 4px; line-height: 1.4; }
.audit-step.done .label { color: var(--success); }
.audit-step.current .label { color: var(--primary); }
.audit-next-card {
  background: linear-gradient(135deg, #e7f5ff 0%, #f8f9fa 100%);
  border: 1px solid #b6d4fe; border-radius: var(--radius-lg);
  padding: 20px 24px; margin-bottom: 24px;
}
.audit-next-card h3 { font-size: 15px; margin: 0 0 8px; }
.audit-next-card p { font-size: 13px; color: var(--text-secondary); margin: 0; line-height: 1.6; }
.audit-next-card .approver {
  display: flex; align-items: center; gap: 12px; margin-top: 14px;
}
.audit-next-card .approver .av {
  width: 40px; height: 40px; border-radius: 50%;
  background: var(--primary); color: #fff;
  display: flex; align-items: center; justify-content: center;
  font-size: 16px; font-weight: 600;
}
.audit-banner {
  display: flex; align-items: center; gap: 12px; flex-wrap: wrap;
  padding: 12px 24px; background: #fff9db; border-bottom: 1px solid #ffe066;
  font-size: 13px;
}
.audit-banner a { color: var(--primary); font-weight: 500; margin-left: auto; }

